def mean(values):
    """Return the arithmetic mean of a non-empty list of numbers."""
    return sum(values) / len(values)

import pytest

from app.calc import mean


@pytest.mark.parametrize(
    ("values", "expected"),
    [([5], 5), ([-3, 1, 2], 0), ([1, 2], 1.5)],
)
def test_mean_cases(values, expected):
    assert mean(values) == expected
